      "attacks": {
        "b0CZ1TMWNNWhztYK": {
          "name": "Punho",
          "damage": "2d12+11 contundente"
        },
        "a9UivdapXwh89X3a": {
          "name": "Pedra",
          "damage": "2d12+7 contundente"
        }
      },
      "actions": {
        "xlEh7Hz3HcY47r4R": {
          "name": "Tremorsense (impreciso) 90 pés (27 metros)",
          "description": ""
        },
        "vXYYcxC29lm6Xqml": {
          "name": "Preso à Terra",
          "description": "Quando não toca o solo sólido, a avalanche elemental fica lenta 1, não pode usar reações e não pode Atropelar."
        },
        "krB0fRntUZ4twRdd": {
          "name": "Desmoronar",
          "description": "Gatilho A avalanche elemental sofre dano de uma fonte hostil enquanto está no topo de uma rocha ou terra\nEfeito A avalanche elemental desmorona no chão, escavando 20 pés (6 metros). Esta Escavação não desencadeia reações.\nA avalanche elemental não pode desmoronar novamente por [[/gmr 1d4 #Recharge Crumble]]{1d4 rodadas}."
        },
        "EIOiFljIAD1Zzdzr": {
          "name": "Pedras Espigadas",
          "description": "10 pés (3 metros).\nPicos de rocha erguem-se de todas as superfícies de pedra na emanação, criando terreno difícil. Uma criatura que se move no terreno sofre 2d8[perfurante] de dano para cada quadrado de espinhos para onde se move (uma criatura Grande ou maior sofre dano apenas uma vez para cada quadrado que se move, mesmo que seu espaço cubra múltiplos quadrados de espinhos). Criaturas com característica terra ignoram todos os efeitos dentro da área.\nA avalanche elemental pode desabilitar ou ativar esta aura usando uma única ação, que possui o traço concentração."
        },
        "vCeTTDUcG0aI8C9H": {
          "name": "Deslizamento da Terra",
          "description": "A avalanche elementar pode escavar qualquer matéria terrestre, incluindo rocha. Ao fazer isso, a avalanche elemental se move em sua velocidade máxima de escavação, não deixando túneis ou sinais de sua passagem."
        },
        "nv9JrM2T8EcaFHSD": {
          "name": "Pedras de amolar",
          "description": "A avalanche elemental causa 4d12[concussão] de dano a cada criatura Caída dentro do alcance corpo a corpo do elemental com um teste de resistência (reflexo, dc:30, básico)."
        },
        "62o3Ky65LWW5uKNE": {
          "name": "Atropelar",
          "description": "Grande ou menor, punho, xeque (reflexo, dc:30, básico)"
        },
        "G6jROiFd4STQSy6X": {
          "name": "Derrubar",
          "description": ""
        }
      },
