        "PjUGlZciMNB5ad4R": {
          "name": "Defesa Cintilante",
          "description": "Gatilho O dragão é alvo de um ataque\nEfeito O dragão mostra suas escamas iridescentes na criatura desencadeadora para desviar o ataque. O dragão ganha Ocultação contra o ataque desencadeador."
        },
        "9XSp9GMrL4MBcCPF": {
          "name": "Exibição cativante",
          "description": "Frequência uma vez a cada 10 minutos\nEfeito O dragão abre as barbatanas da cabeça, criando uma exibição radiante de cores fascinantes. Cada criatura em um @Template[emanation|distance:30] deve ter sucesso em um teste (vontade, dc:33, opções:efeito de área,inflige:deslumbrado,inflige:lentidão) salvar ou ficará Deslumbrada e Desacelerada 1 (ou Desacelerada 2 em uma falha crítica) por 1 rodada. Independentemente do resultado, a criatura fica temporariamente imune à Exibição Cativante por 1 minuto."
        },
        "WMdK1rdUjXn9ZjQJ": {
          "name": "Frenesi Dracônico",
          "description": "O dragão faz dois golpes de garra e um golpe de cauda em qualquer ordem."
        },
        "jgWjQm6QarRsD1eE": {
          "name": "Momento Dracônico",
          "description": "O dragão recarrega sua Respiração Alucinatória sempre que consegue um acerto crítico com um Golpe."
        },
        "cuSg2YxJeOWsi3XS": {
          "name": "Respiração Alucinatória",
          "description": "O dragão respira uma nuvem que ataca os sentidos e causa 12d6[mental|options:area-damage] de dano em um salvamento de @Template[cone|distance:40] (check (will, dc:33, options:area-effect)). Uma criatura que falhe no teste também fica Confusa por 1 rodada (1 minuto em caso de falha crítica) e fica temporariamente imune a ser confundida por Respiração Alucinatória por 1 hora.\nO dragão não pode usar Respiração Alucinatória novamente por [[/gmr 1d4 #Recharge Respiração Alucinatória]]{1d4 rodadas}."
        },
        "YGFIBzztMdCKAOGu": {
          "name": "Mordida Pulmonante",
          "description": "O dragão lança a cabeça para frente, fazendo um golpe de mandíbula com alcance estendido de 25 pés (7,5 metros)."
        },
        "5Ta2GgqbQiT1PrJW": {
          "name": "Ataque furtivo",
          "description": "Os Golpes do dragão causam 2d6 de dano de precisão adicional aos alvos Desprotegidos."
        }
